  const wire=(phase:'start'|'end',result?:any)=>{const data:any={rootCallId:input.callId,parentCallId:input.callId,subCallId:inner.callId,name:inner.name,arguments:mode==='record'?structuredClone(args):JSON.stringify(args),...(phase==='end'?{isError:result.isError}:{})};mutate?.(data,phase);return data;};
